import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uniform, uv, vec2, vec3, float, mix, Fn } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, DataTexture, RGBAFormat,
    SRGBColorSpace, DoubleSide
  } = ctx.THREE;

  const group = new Group();
  group.name = 'hub-pricing-card-2';

  // --- Atlas region: rect 0,0,512,320 (single-region atlas -> full texture).
  const texUniform = uniform(null);

  // Placeholder ink-tinted 1px until the real cached asset resolves.
  const placeholder = new DataTexture(
    new Uint8Array([11, 11, 16, 255]),
    1, 1, RGBAFormat
  );
  placeholder.needsUpdate = true;
  texUniform.value = placeholder;

  // Subtle engineered grain — no soft pastel blur, no plain flat fill.
  const grain = Fn(() => {
    const g = uv().add(vec2(float(0.137), float(0.291)));
    const n = g.x.mul(12.9898).add(g.y.mul(78.233)).sin().fract();
    return n.sub(float(0.5)).mul(float(0.035));
  })();

  const baseColorNode = mix(
    vec3(float(0.043), float(0.043), float(0.063)),
    texture(texUniform).rgb,
    float(1.0).sub(grain)
  );

  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    toneMapped: false
  });
  mat.colorNode = baseColorNode;

  // Aspect 512:320 = 1.6 — sized to sit on the right edge of the hub frame.
  const W = 1.4;
  const H = W * (320 / 512);
  const geo = new PlaneGeometry(W, H, 1, 1);
  const mesh = new Mesh(geo, mat);
  mesh.renderOrder = 2;
  group.add(mesh);

  // Thin accent spine on the leading edge (signal red, <=10% of frame).
  const accentMat = new MeshBasicNodeMaterial({ transparent: true, toneMapped: false });
  accentMat.colorNode = vec3(float(1.0), float(0.165), float(0.22));
  const accentGeo = new PlaneGeometry(0.022, H * 0.78, 1, 1);
  const accent = new Mesh(accentGeo, accentMat);
  accent.position.set(-W * 0.5 + 0.014, 0.0, 0.002);
  accent.renderOrder = 3;
  group.add(accent);

  // --- Resolve the cached texture and swap the uniform.
  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      try { tex.colorSpace = SRGBColorSpace; } catch (e) {}
      if (texUniform.value && texUniform.value !== placeholder && texUniform.value.dispose) {
        // real texture will be owned by the loader cache; do not dispose here.
      }
      texUniform.value = tex;
      mat.needsUpdate = true;
    });
  }

  // --- Entrance: fade-up + weighted settle, no linear easing on hero motion.
  group.scale.set(0.94, 0.94, 0.94);
  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
  tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  tl.fromTo(mat, { opacity: 0 }, { opacity: 1, duration: 0.7 }, 0);
  tl.fromTo(accentMat, { opacity: 0 }, { opacity: 1, duration: 0.6 }, 0.18);
  tl.fromTo(
    group.position,
    { y: group.position.y + 0.18 },
    { y: group.position.y, duration: 0.7, ease: 'power3.out' },
    0
  );

  // --- Event surface (no DOM listeners; parent coordinates nav via ctx.emit).
  group.userData.handlers = {
    onPointerOver: () => {},
    onPointerOut: () => {},
    onClick: () => {
      ctx.emit('navigate', { to: 'hub-pricing' });
    }
  };

  // --- Cleanup: dispose GPU resources + kill GSAP timeline.
  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    accentGeo.dispose();
    mat.dispose();
    accentMat.dispose();
    if (placeholder && placeholder.dispose) placeholder.dispose();
  };

  return group;
}
